/**
 * Open a server-rendered PDF blob in a new tab and trigger the browser's print dialog.
 *
 * This is now the ONLY print path. Documents used to be assembled as HTML in the browser and
 * printed from a blank pop-up, which meant Chrome stamped its own header and footer on every
 * printout (the date, the title, `about:blank` and a page counter) with no way to suppress
 * them from CSS, could not produce a page number of its own, and - the real problem - printed
 * whatever the page had on screen under a "Generated by <user>" attribution the server had
 * never verified. See backend/src/utils/printDocument.ts.
 *
 * Printing an already-rendered PDF avoids the furniture entirely: Chrome draws those headers
 * only for pages it lays out itself, not for a PDF it is displaying.
 *
 * Returns false if the pop-up was blocked so the caller can surface a message.
 */
export function printPdfBlob(blob: Blob): boolean {
  const url = URL.createObjectURL(blob);
  const win = window.open(url, '_blank');
  if (!win) {
    URL.revokeObjectURL(url);
    return false;
  }
  let printed = false;
  const trigger = () => {
    if (printed) return;
    printed = true;
    try {
      win.focus();
      win.print();
    } catch {
      /* the embedded PDF viewer provides its own print control */
    }
  };
  win.addEventListener('load', trigger);
  // Fallback: some browsers don't fire load for the embedded PDF viewer.
  setTimeout(trigger, 1500);
  setTimeout(() => URL.revokeObjectURL(url), 60000);
  return true;
}
